        var d=new DOMParser().parseFromString(t,'text/html'),items=$$('#postGrid .card',d);
        items.forEach(function(c,i){c.style.setProperty('--d',(i%4)*90+'ms');grid.appendChild(D.importNode(c,true))});
        decorate(grid);
