/* ---------- single post ---------- */
var pb=$('#postBody');
if(pb){
  var url=location.href.split('#')[0].split('?')[0],ttl=($('.pt')||{}).textContent||D.title;
  var rt=$('#rt');
  if(rt){var wc=(pb.innerText||'').trim().split(/\s+/).length;rt.textContent=Math.max(1,Math.round(wc/220))+' min read'}
  var av=$('.abox .av');if(av){av.textContent=(av.getAttribute('data-name')||'?').trim().charAt(0).toUpperCase()}

  /* lazy images + lightbox */
  $$('img',pb).forEach(function(im){im.loading='lazy';im.decoding='async';im.removeAttribute('height')});
  pb.addEventListener('click',function(e){
    var im=e.target.closest&&e.target.closest('img');if(!im)return;
    e.preventDefault();
    var src=im.currentSrc||im.src;src=src.replace(/\/s\d+(-c)?\//,'/s1600/').replace(/\/w\d+-h\d+[^/]*\//,'/s1600/');
    var o=D.createElement('div');o.className='lb';o.innerHTML='<img alt="'+esc(im.alt||'')+'" src="'+esc(src)+'"/>';
    o.addEventListener('click',function(){o.remove()});B.appendChild(o);
  });

  /* table of contents + scroll spy */
  var hs=$$('h2,h3',pb);
  if(hs.length>=3){
    hs.forEach(function(h,i){if(!h.id){h.id=(h.textContent.trim().toLowerCase().replace(/[^\w]+/g,'-').replace(/^-+|-+$/g,'')||'s')+'-'+i}});
    var toc=D.createElement('details');toc.className='toc';toc.open=true;
    toc.innerHTML='<summary>Table of contents</summary><ol>'+hs.map(function(h){return '<li class="'+(h.tagName==='H3'?'sub':'')+'"><a href="#'+h.id+'">'+esc(h.textContent)+'</a></li>'}).join('')+'</ol>';
    pb.insertBefore(toc,pb.firstChild);
    if('IntersectionObserver' in W){
      var map={};$$('a',toc).forEach(function(a){map[a.getAttribute('href').slice(1)]=a});
      var so=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){$$('a.act',toc).forEach(function(a){a.classList.remove('act')});var a=map[e.target.id];if(a)a.classList.add('act')}})},{rootMargin:'-80px 0px -70% 0px'});
      hs.forEach(function(h){so.observe(h)});
    }
  }

  /* share buttons */
  var sh=$('#share');
  if(sh){
    var eu=encodeURIComponent(url),et=encodeURIComponent(ttl);
    var urls={fb:'https://www.facebook.com/sharer/sharer.php?u='+eu,x:'https://twitter.com/intent/tweet?url='+eu+'&text='+et,wa:'https://wa.me/?text='+et+'%20'+eu,tg:'https://t.me/share/url?url='+eu+'&text='+et};
    $$('a[data-net]',sh).forEach(function(a){a.href=urls[a.getAttribute('data-net')]||'#'});
    var cp=$('[data-net="cp"]',sh);if(cp){cp.addEventListener('click',function(){copy(url,'Link copied')})}
    if(navigator.share){
      var nb=D.createElement('button');nb.type='button';nb.textContent='Share\u2026';
      nb.addEventListener('click',function(){navigator.share({title:ttl,url:url}).catch(function(){})});sh.appendChild(nb);
    }
  }

  /* related posts */
  var rel=$('#related');
  if(rel){
    var first=$('.plabels a'),lab=first?first.textContent.trim():null;
    (lab?feed(lab,6):Promise.resolve([])).then(function(a){
      a=a.filter(function(p){return p.u.split('?')[0]!==url});
      return a.length>=2?a:feed(null,6).then(function(b){return b.filter(function(p){return p.u.split('?')[0]!==url})});
    }).then(function(a){
      a=a.slice(0,4);if(!a.length)return;
      $('.cards',rel).innerHTML=a.map(card).join('');rel.hidden=false;
    }).catch(function(){});
  }
}

