$$('.adwrap').forEach(function(w){if(!$('.widget',w)){w.classList.add('off')}});

/* ---------- smooth anchors (TOC) ---------- */
D.addEventListener('click',function(e){
  var a=e.target.closest&&e.target.closest('a[href^="#"]');
  if(a&&a.getAttribute('href').length>1){var t=D.getElementById(a.getAttribute('href').slice(1));if(t){e.preventDefault();t.scrollIntoView({behavior:REDUCE?'auto':'smooth',block:'start'});if(history.replaceState)history.replaceState(null,'',a.getAttribute('href'))}}
});
})();

/* ================= MOTION SYSTEM ================= */
(function(){
'use strict';
var D=document,W=window,DE=D.documentElement,B=D.body;
function $(s,c){return (c||D).querySelector(s)}
function $$(s,c){return Array.prototype.slice.call((c||D).querySelectorAll(s))}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
var REDUCE=W.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches;
var FINE=W.matchMedia&&matchMedia('(hover:hover) and (pointer:fine)').matches;
var HAS_IO='IntersectionObserver' in W;

/* ---------- scroll reveal for posts, cards, rows, share, comments ---------- */
var SEL='.card,.li,.pr,.share,.pnav a,.abox,.comments';
var seen=new WeakSet(),rio=null;
if(HAS_IO){
  rio=new IntersectionObserver(function(es){
    var vis=es.filter(function(e){return e.isIntersecting}).sort(function(a,b){
      var A=a.boundingClientRect,Bq=b.boundingClientRect;return (A.top-Bq.top)||(A.left-Bq.left)});
    vis.forEach(function(e,i){
      var el=e.target;
      if(el.classList.contains('card')||el.classList.contains('li')||el.classList.contains('pr')){el.style.setProperty('--d',Math.min(i,6)*85+'ms')}
      if(el.classList.contains('share')){$$(':scope > *',el).forEach(function(c,k){c.style.setProperty('--i',k)})}
      el.classList.add('in');rio.unobserve(el);
    });
  },{rootMargin:'0px 0px -6% 0px',threshold:.08});
}
function watch(root){
  $$(SEL,root).forEach(function(el){
    if(seen.has(el))return;seen.add(el);
    if(rio){rio.observe(el)}else{el.classList.add('in')}
  });
}

/* ---------- image blur-up ---------- */
function imgs(){$$('.ph img:not(.ld)').forEach(function(im){if(im.complete&&im.naturalWidth){im.classList.add('ld')}})}
D.addEventListener('load',function(e){if(e.target&&e.target.tagName==='IMG'){e.target.classList.add('ld')}},true);
setTimeout(function(){$$('.ph img:not(.ld)').forEach(function(im){im.classList.add('ld')})},4000);

/* ---------- post body blocks ---------- */
var pb=$('#postBody');
if(pb){
  var kids=$$(':scope > *',pb);
  if(kids.length===1&&kids[0].tagName==='DIV'){kids=$$(':scope > *',kids[0])}
  kids.forEach(function(k){if(!/^(SCRIPT|STYLE|BR)$/.test(k.tagName)){k.classList.add('pr')}});
}

/* ---------- post title: word-by-word reveal ---------- */
var pt=$('.pt');
if(pt&&!REDUCE){
  var tx=pt.textContent.trim();
  pt.setAttribute('aria-label',tx);
  pt.innerHTML=tx.split(/\s+/).map(function(w,i){
    var inner=i===0?'<em class="fl">'+esc(w.charAt(0))+'</em>'+esc(w.slice(1)):esc(w);
    return '<span class="w" aria-hidden="true"><span style="--i:'+i+'">'+inner+'</span></span>';
  }).join(' ');
}

/* ---------- observe everything now + whenever content is added ---------- */
watch(D);imgs();
var mt;
new MutationObserver(function(){clearTimeout(mt);mt=setTimeout(function(){watch(D);imgs()},60)}).observe(B,{childList:true,subtree:true});

/* ---------- button ripple ---------- */
var RIP='.btn-more,.btn-o,.tag,.share a,.share button,.ib,.nav a.pill,.pnav a,.sbox button,.soc a';
D.addEventListener('pointerdown',function(e){
  if(REDUCE||e.button)return;
  var t=e.target.closest&&e.target.closest(RIP);if(!t)return;
  t.classList.add('rpl');
  var r=t.getBoundingClientRect(),s=Math.max(r.width,r.height)*2.2,sp=D.createElement('span');
  sp.className='rp';
  sp.style.cssText='width:'+s+'px;height:'+s+'px;left:'+(e.clientX-r.left-s/2)+'px;top:'+(e.clientY-r.top-s/2)+'px';
  t.appendChild(sp);setTimeout(function(){sp.remove()},700);
},{passive:true});

/* ---------- magnetic buttons (mouse only) ---------- */
if(FINE&&!REDUCE){
  var MAG='.btn-more,.nav a.pill,.btn-o,.share a,.share button,#up,.sbox button',mc=null;
  function mreset(el){if(!el)return;el.style.removeProperty('--tx');el.style.removeProperty('--ty');}
  D.addEventListener('pointermove',function(e){
    if(e.pointerType!=='mouse')return;
    var t=e.target.closest&&e.target.closest(MAG);
    if(mc&&mc!==t){mreset(mc);mc=null}
    if(!t)return;
    t.classList.add('mag');mc=t;
    var r=t.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2);
    t.style.setProperty('--tx',Math.max(-7,Math.min(7,dx*.22))+'px');
    t.style.setProperty('--ty',Math.max(-6,Math.min(6,dy*.3))+'px');
  },{passive:true});
  D.documentElement.addEventListener('mouseleave',function(){mreset(mc);mc=null});
}

/* ---------- 3D tilt + light glare on article images ---------- */
if(FINE&&!REDUCE){
  var tcur=null,traf=0;
  function tclear(){if(tcur){tcur.el.classList.remove('on');tcur.el.style.setProperty('--rx','0deg');tcur.el.style.setProperty('--ry','0deg');tcur=null}}
  D.addEventListener('pointermove',function(e){
    if(e.pointerType!=='mouse')return;
    var host=e.target.closest&&e.target.closest('.card,.prop>div,.sfeat');
    if(!host){tclear();return}
    var el=$('.thumb',host)||$('.ln',host);if(!el)return;
    if(tcur&&tcur.el!==el){tclear()}
    var cx=e.clientX,cy=e.clientY;
    cancelAnimationFrame(traf);
    traf=requestAnimationFrame(function(){
      var r=el.getBoundingClientRect(),px=(cx-r.left)/r.width,py=(cy-r.top)/r.height;
      if(px<-.15||px>1.15||py<-.4||py>1.4){tclear();return}
      el.classList.add('tilt','on');tcur={el:el};
      el.style.setProperty('--ry',((px-.5)*9).toFixed(2)+'deg');
      el.style.setProperty('--rx',((.5-py)*7).toFixed(2)+'deg');
      el.style.setProperty('--mx',(px*100).toFixed(1)+'%');el.style.setProperty('--my',(py*100).toFixed(1)+'%');
    });
  },{passive:true});
  D.documentElement.addEventListener('mouseleave',tclear);
}

/* ---------- header: hide on scroll down, reveal on scroll up; back-to-top ring ---------- */
var hd=$('#hd'),up=$('#up'),lastY=W.pageYOffset,sraf=0;
function onScroll(){
  sraf=0;var y=W.pageYOffset,dy=y-lastY,h=DE.scrollHeight-W.innerHeight;
  if(up){up.style.setProperty('--p',h>0?Math.round(y/h*100):0)}
  if(hd&&!REDUCE){
    var open=$('#mainNav.open')||$('#sbox.open');
    if(open||y<300||dy<-6){hd.classList.remove('hide')}
    else if(dy>8){hd.classList.add('hide')}
  }
  if(Math.abs(dy)>4){lastY=y}
}
W.addEventListener('scroll',function(){if(!sraf){sraf=requestAnimationFrame(onScroll)}},{passive:true});onScroll();

/* ---------- mobile menu: staggered links ---------- */
$$('#mainNav a').forEach(function(a,i){a.style.setProperty('--i',i)});

/* ---------- hero: swipe on touch screens ---------- */
var hero=$('#hero'),sx=0,sy=0;
if(hero){
  hero.addEventListener('touchstart',function(e){sx=e.touches[0].clientX;sy=e.touches[0].clientY},{passive:true});
  hero.addEventListener('touchend',function(e){
    var dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy;
    if(Math.abs(dx)<50||Math.abs(dx)<Math.abs(dy))return;
    var d=$$('.dots button',hero),i=d.findIndex(function(b){return b.classList.contains('on')});
    if(i<0||d.length<2)return;
    d[(i+(dx<0?1:-1)+d.length)%d.length].click();
  },{passive:true});
}

/* ---------- copy-link feedback + confetti ---------- */
function burst(x,y){
  if(REDUCE)return;
  var cols=['#ffc20e','#e5482c','#1d5fc4','#22c55e','#8db8ff'];
  for(var i=0;i<16;i++){
    var s=D.createElement('i'),a=Math.random()*6.283,d=40+Math.random()*70;
    s.className='bp';
    s.style.cssText='left:'+x+'px;top:'+y+'px;background:'+cols[i%5]+';--bx:'+(Math.cos(a)*d).toFixed(0)+'px;--by:'+(Math.sin(a)*d-24).toFixed(0)+'px;--br:'+Math.round(Math.random()*540-270)+'deg';
    B.appendChild(s);(function(n){setTimeout(function(){n.remove()},900)})(s);
  }
}
D.addEventListener('click',function(e){
  var c=e.target.closest&&e.target.closest('[data-net="cp"]');
  if(c){
    var old=c.textContent;c.classList.add('ok');c.textContent='Copied \u2713';burst(e.clientX,e.clientY);
    setTimeout(function(){c.classList.remove('ok');c.textContent=old},1700);
  }
});

/* ---------- theme toggle: circular reveal ---------- */
var tg=$('#tg');
if(tg){
  tg.addEventListener('click',function(e){
    tg.classList.remove('spin');void tg.offsetWidth;if(!REDUCE){tg.classList.add('spin')}
    if(REDUCE||!D.startViewTransition)return;       /* fall back to the basic toggle */
    e.stopImmediatePropagation();
    var x=e.clientX||tg.getBoundingClientRect().left,y=e.clientY||tg.getBoundingClientRect().top;
    var r=Math.hypot(Math.max(x,W.innerWidth-x),Math.max(y,W.innerHeight-y));
    var t=D.startViewTransition(function(){
      var d=DE.getAttribute('data-theme')==='dark';
      if(d){DE.removeAttribute('data-theme')}else{DE.setAttribute('data-theme','dark')}
      try{localStorage.setItem('theme',d?'light':'dark')}catch(err){}
    });
    t.ready.then(function(){
      DE.animate({clipPath:['circle(0px at '+x+'px '+y+'px)','circle('+r+'px at '+x+'px '+y+'px)']},
        {duration:700,easing:'cubic-bezier(.2,.7,.2,1)',pseudoElement:'::view-transition-new(root)'});
    }).catch(function(){});
  },true);
}

/* ---------- page transition between pages ---------- */
if(!REDUCE){
  D.addEventListener('click',function(e){
    if(e.defaultPrevented||e.button||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;
    var a=e.target.closest&&e.target.closest('a[href]');
    if(!a||a.target||a.hasAttribute('download'))return;
    var u;try{u=new URL(a.href,location.href)}catch(x){return}
    if(u.origin!==location.origin||/^(javascript|mailto|tel):/.test(a.getAttribute('href')))return;
    if(u.pathname===location.pathname&&u.search===location.search)return;
    if(/\/feeds\/|\/b\/|\.xml$/.test(u.pathname))return;
    e.preventDefault();B.classList.add('leaving');
    setTimeout(function(){location.href=a.href},230);
  });
  W.addEventListener('pageshow',function(e){if(e.persisted){B.classList.remove('leaving')}});
}
})();

